CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "action_time" timestamp with time zone NOT NULL, "user_id" bigint NOT NULL, "content_type_id" integer NULL, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(255) NOT NULL, "content_type_id" integer NOT NULL, "codename" varchar(100) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "group_id" integer NOT NULL, "permission_id" integer NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" timestamp with time zone NOT NULL);
CREATE TABLE "facultades" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(150) NOT NULL UNIQUE, "codigo" varchar(20) NOT NULL);
CREATE TABLE "programas" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(150) NOT NULL, "facultad_id" bigint NOT NULL, "nivel" varchar(50) NOT NULL);
CREATE TABLE "ecosistemas" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nombre" varchar(150) NOT NULL UNIQUE, "descripcion" text NOT NULL);
CREATE TABLE "profesores" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "usuario_id" bigint NOT NULL UNIQUE, "facultad_id" bigint NULL, "especialidad" varchar(100) NOT NULL);
CREATE TABLE "estudiantes" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "usuario_id" bigint NOT NULL UNIQUE, "programa_id" bigint NULL, "semestre" integer NOT NULL);
CREATE TABLE "certificados" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "usuario_id" bigint NOT NULL, "rol_participacion" varchar(20) NOT NULL, "codigo_verificacion" uuid NOT NULL UNIQUE, "horas" integer NULL CHECK ("horas" >= 0), "emitido_en" timestamp with time zone NOT NULL, "emitido_por_id" bigint NULL, "archivo" varchar(100) NULL);
CREATE TABLE "cierre_agendacierre" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL UNIQUE, "fecha_hora" timestamp with time zone NULL, "espacio" varchar(200) NOT NULL, "recursos" text NOT NULL, "invitados" text NOT NULL, "agenda" text NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "cierres_reto" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL UNIQUE, "acta_url" varchar(100) NULL, "notas" text NOT NULL, "encuesta_enviada" boolean NOT NULL, "cerrado_por_id" bigint NULL, "cerrado_en" timestamp with time zone NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "reconocimientos" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "cierre_id" bigint NOT NULL, "usuario_id" bigint NULL, "nombre_destinatario" varchar(150) NOT NULL, "descripcion" text NOT NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "cierre_entregablefinal" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "cierre_id" bigint NOT NULL, "nombre" varchar(180) NOT NULL, "archivo" varchar(100) NOT NULL, "cargado_por_id" bigint NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "cierre_encuestasatisfaccion" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "cierre_id" bigint NOT NULL, "participante_id" bigint NOT NULL, "calificacion" smallint NULL CHECK ("calificacion" >= 0), "comentario" text NOT NULL, "respondida_en" timestamp with time zone NULL, "creada_en" timestamp with time zone NOT NULL);
CREATE TABLE "empresas" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "nit" varchar(20) NOT NULL UNIQUE, "razon_social" varchar(150) NOT NULL, "sector_industrial" varchar(100) NOT NULL, "fecha_creacion" date NOT NULL, "estado_validacion" varchar(20) NOT NULL, "estado_listas_restrictivas" varchar(20) NOT NULL, "evidencia_listas" varchar(100) NULL, "fecha_ultima_actualizacion" timestamp with time zone NOT NULL, "observaciones_admin" text NULL, "renuncio_a_convenio" boolean NOT NULL, "estado_convenio" varchar(20) NOT NULL, "fecha_vencimiento_convenio" date NULL, "usuario_id" bigint NULL UNIQUE);
CREATE TABLE "contactos_empresa" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "empresa_id" bigint NOT NULL, "nombre" varchar(100) NOT NULL, "cargo" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "telefono" varchar(20) NOT NULL, "es_principal" boolean NOT NULL);
CREATE TABLE "documentos_empresas" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "empresa_id" bigint NOT NULL, "tipo_documento" varchar(50) NOT NULL, "archivo" varchar(100) NULL, "estado" varchar(15) NOT NULL, "fecha_expedicion" date NULL, "fecha_vencimiento" date NULL, "fecha_carga" timestamp with time zone NOT NULL, "motivo_rechazo" text NULL);
CREATE TABLE "entregables" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "equipo_id" bigint NULL, "estudiante_id" bigint NOT NULL, "titulo" varchar(180) NOT NULL, "es_final" boolean NOT NULL, "puntaje_maximo" numeric(6, 2) NOT NULL, "archivo" varchar(100) NOT NULL, "comentario_estudiante" text NULL, "comentario_profesor" text NULL, "nota" numeric(6, 2) NULL, "fecha_entrega" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "estado" varchar(20) NOT NULL);
CREATE TABLE "evaluacion_rubrica" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "nombre" varchar(150) NOT NULL, "descripcion" text NOT NULL, "activa" boolean NOT NULL, "creada_por_id" bigint NULL, "creada_en" timestamp with time zone NOT NULL);
CREATE TABLE "evaluacion_criteriorubrica" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "rubrica_id" bigint NOT NULL, "nombre" varchar(150) NOT NULL, "descripcion" text NOT NULL, "puntaje_maximo" numeric(6, 2) NOT NULL, "orden" smallint NOT NULL CHECK ("orden" >= 0));
CREATE TABLE "evaluaciones" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "entregable_id" bigint NOT NULL, "profesor_id" bigint NOT NULL, "nota" numeric(6, 2) NOT NULL, "comentario" text NOT NULL, "rubrica_id" bigint NULL, "fecha" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "evaluacion_evaluacioncriterio" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "evaluacion_id" bigint NOT NULL, "criterio_id" bigint NOT NULL, "puntaje" numeric(6, 2) NOT NULL);
CREATE TABLE "evaluacion_comentarioentregable" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "entregable_id" bigint NOT NULL, "autor_id" bigint NULL, "comentario" text NOT NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "hackathons" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL UNIQUE, "reglas" text NOT NULL, "estado" varchar(20) NOT NULL, "resultados_publicados" boolean NOT NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "etapas_hackaton" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "hackathon_id" bigint NOT NULL, "tipo" varchar(30) NOT NULL, "titulo" varchar(150) NOT NULL, "inicia_en" timestamp with time zone NULL, "termina_en" timestamp with time zone NULL, "orden" smallint NOT NULL CHECK ("orden" >= 0));
CREATE TABLE "jurados_hackaton" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "hackathon_id" bigint NOT NULL, "usuario_id" bigint NULL, "nombre" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "especialidad" varchar(150) NOT NULL);
CREATE TABLE "votaciones_hackaton" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "hackathon_id" bigint NOT NULL, "jurado_id" bigint NOT NULL, "equipo_id" bigint NOT NULL, "puntaje" numeric(4, 2) NOT NULL, "comentario" text NOT NULL, "fecha" timestamp with time zone NOT NULL);
CREATE TABLE "inscripciones_hackaton" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "hackathon_id" bigint NOT NULL, "equipo_id" bigint NOT NULL, "estado" varchar(20) NOT NULL, "inscrito_por_id" bigint NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "notificaciones" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "usuario_id" bigint NOT NULL, "tipo" varchar(20) NOT NULL, "evento" varchar(60) NOT NULL, "titulo" varchar(200) NOT NULL, "mensaje" text NOT NULL, "leida" boolean NOT NULL, "leida_en" timestamp with time zone NULL, "link" varchar(300) NOT NULL, "clave_dedupe" varchar(120) NOT NULL, "enviada_por_correo" boolean NOT NULL, "error_envio" text NOT NULL, "creada_en" timestamp with time zone NOT NULL);
CREATE TABLE "preferencias_notificacion" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "usuario_id" bigint NOT NULL UNIQUE, "recibir_email" boolean NOT NULL, "recibir_recordatorios" boolean NOT NULL, "eventos_silenciados" jsonb NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "postulaciones" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "estudiante_id" bigint NOT NULL, "fecha_postulacion" timestamp with time zone NOT NULL, "estado" varchar(20) NOT NULL, "motivacion" text NOT NULL, "habilidades" text NOT NULL, "semestre" integer NULL, "programa" varchar(150) NOT NULL);
CREATE TABLE "equipos" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "nombre" varchar(100) NOT NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "miembros_equipo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "equipo_id" bigint NOT NULL, "estudiante_id" bigint NOT NULL, "rol" varchar(20) NOT NULL, "fecha_ingreso" timestamp with time zone NOT NULL);
CREATE TABLE "retos_favoritos" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "usuario_id" bigint NOT NULL, "reto_id" bigint NOT NULL, "fecha" timestamp with time zone NOT NULL);
CREATE TABLE "presupuestos" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL UNIQUE, "monto_total" numeric(12, 2) NOT NULL, "alerta_80_enviada" boolean NOT NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "gastos" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "presupuesto_id" bigint NOT NULL, "categoria" varchar(30) NOT NULL, "monto" numeric(12, 2) NOT NULL, "descripcion" text NOT NULL, "comprobante" varchar(100) NULL, "registrado_por_id" bigint NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "reportes_generados" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "usuario_id" bigint NOT NULL, "formato" varchar(10) NOT NULL, "filtros" jsonb NULL, "archivo" varchar(100) NULL, "enviado_por_email" boolean NOT NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "retos" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "empresa_id" bigint NOT NULL, "tipo" varchar(20) NOT NULL, "titulo" varchar(180) NOT NULL, "descripcion" text NOT NULL, "area" varchar(120) NOT NULL, "nivel_academico" varchar(120) NOT NULL, "facultad_id" bigint NULL, "programa_id" bigint NULL, "ecosistema_id" bigint NULL, "fecha_inicio_tentativa" date NULL, "fecha_fin_tentativa" date NULL, "fecha_limite_postulacion" date NULL, "premios" text NOT NULL, "documento_soporte" varchar(100) NULL, "criterios_evaluacion" text NOT NULL, "estado" varchar(20) NOT NULL, "consecutivo" integer NULL CHECK ("consecutivo" >= 0), "anio_consecutivo" smallint NULL CHECK ("anio_consecutivo" >= 0), "comentarios_revision" text NOT NULL, "fecha_envio_revision" timestamp with time zone NULL, "fecha_aprobacion" timestamp with time zone NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL, "tiene_convenio_institucional" boolean NOT NULL, "eliminado_en" timestamp with time zone NULL, CONSTRAINT "reto_consecutivo_unico_por_tipo_y_anio" UNIQUE ("tipo", "anio_consecutivo", "consecutivo"));
CREATE TABLE "historial_estados_reto" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "estado_anterior" varchar(20) NOT NULL, "estado_nuevo" varchar(20) NOT NULL, "comentario" text NOT NULL, "realizado_por_id" bigint NULL, "fecha" timestamp with time zone NOT NULL);
CREATE TABLE "retos_retoarchivo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "archivo" varchar(100) NOT NULL, "nombre_original" varchar(255) NOT NULL, "tamano" bigint NOT NULL CHECK ("tamano" >= 0), "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "equipos_reto_academico" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "nombre_equipo" varchar(100) NOT NULL, "equipo_espejo_id" bigint NULL UNIQUE);
CREATE TABLE "equipos_reto_academico_profesores" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "equiporetoacademico_id" bigint NOT NULL, "usuario_id" bigint NOT NULL);
CREATE TABLE "equipos_reto_academico_estudiantes" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "equiporetoacademico_id" bigint NOT NULL, "usuario_id" bigint NOT NULL);
CREATE TABLE "equipos_reto_academico_expertos_invitados" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "equiporetoacademico_id" bigint NOT NULL, "usuario_id" bigint NOT NULL);
