CREATE TABLE "integraciones_academicas" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "profesor_id" bigint NOT NULL, "facultad" varchar(140) NOT NULL, "nivel_formacion" varchar(120) NOT NULL, "programa_academico" varchar(160) NOT NULL, "ecosistema" varchar(140) NOT NULL, "descripcion" text NOT NULL, "alcance" text NOT NULL, "entregable_esperado" varchar(180) NOT NULL, "cronograma_sesiones" text NOT NULL, "equipo_profesores" text NOT NULL, "equipo_estudiantes" text NOT NULL, "expertos_invitados" text NOT NULL, "requerimientos_empresa" text NOT NULL, "requerimientos_internos" text NOT NULL, "espacio_fisico" varchar(180) NOT NULL, "estado" varchar(20) NOT NULL, "comentarios_revision" text NOT NULL, "fecha_envio_revision" timestamp with time zone NULL, "fecha_aprobacion" timestamp with time zone NULL, "creado_en" timestamp with time zone NOT NULL, "actualizado_en" timestamp with time zone NOT NULL);
CREATE TABLE "seguimientos_reto" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "reto_id" bigint NOT NULL, "tipo_sesion" varchar(30) NOT NULL, "fecha_sesion" date NOT NULL, "porcentaje_avance" smallint NOT NULL CHECK ("porcentaje_avance" >= 0), "avances" text NOT NULL, "observaciones" text NOT NULL, "acuerdos" text NOT NULL, "creado_por_id" bigint NULL, "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "seguimiento_seguimientoarchivo" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "seguimiento_id" bigint NOT NULL, "archivo" varchar(100) NOT NULL, "nombre_original" varchar(255) NOT NULL, "tamano" bigint NOT NULL CHECK ("tamano" >= 0), "creado_en" timestamp with time zone NOT NULL);
CREATE TABLE "historial_estados" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "content_type_id" integer NOT NULL, "object_id" bigint NOT NULL CHECK ("object_id" >= 0), "campo" varchar(50) NOT NULL, "estado_anterior" varchar(30) NOT NULL, "estado_nuevo" varchar(30) NOT NULL, "comentario" text NOT NULL, "realizado_por_id" bigint NULL, "fecha" timestamp with time zone NOT NULL);
